{
  "status": "graded",
  "criteria": [
    {
      "criterion_id": "c1",
      "level_id": "met",
      "reason": "明确使用只依赖状态的 baseline 来降低共同回报波动。",
      "evidence_quote": "Use a baseline conditioned on the state rather than the chosen action to remove common return fluctuations.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c2",
      "level_id": "met",
      "reason": "将学习信号中心化为 advantage，反映动作相对质量。",
      "evidence_quote": "Center the learning signal as an advantage so it reflects relative action quality.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c3",
      "level_id": "met",
      "reason": "增大 batch 或并行轨迹可降低采样噪声。",
      "evidence_quote": "Larger batches or parallel trajectories reduce sampling noise.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c4",
      "level_id": "met",
      "reason": "多步估计或 GAE 允许偏差-方差折中。",
      "evidence_quote": "Multi-step estimators or GAE allow a bias-variance tradeoff.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c5",
      "level_id": "met",
      "reason": "标准化 advantage 常改善数值尺度。",
      "evidence_quote": "Standardizing advantages often improves numerical scaling.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c6",
      "level_id": "met",
      "reason": "熵正则保持探索，避免因早期噪声过早确定。",
      "evidence_quote": "Entropy regularization helps maintain exploration instead of becoming deterministic because of noisy early evidence.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c7",
      "level_id": "met",
      "reason": "梯度裁剪或约束策略变化可防止单次更新过大。",
      "evidence_quote": "Clip gradients or constrain policy movement to avoid one excessive update.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c8",
      "level_id": "met",
      "reason": "报告包含回报、熵、价值预测误差和 KL 或策略变化指标。",
      "evidence_quote": "Report return, entropy, value prediction error and KL or another measure of policy change.",
      "evidence_source": "text"
    }
  ]
}
